(function () {
  'use strict';

  // --- Data ---------------------------------------------------------------
  const featured = [
    { id: 'f1', cat: 'Kitchen', name: 'Stoneware Dinner Plate', price: 28, badge: 'New', palette: ['#e8dfd1', '#c9b59a'] },
    { id: 'f2', cat: 'Living', name: 'Linen Throw Blanket', price: 110, oldPrice: 140, badge: 'Sale', palette: ['#4f6b5d', '#2c4337'] },
    { id: 'f3', cat: 'Lighting', name: 'Brass Table Lamp', price: 245, badge: 'New', palette: ['#d4a76a', '#8a6a3f'] },
    { id: 'f4', cat: 'Bath', name: 'Organic Cotton Towel', price: 42, palette: ['#efe2cd', '#b8a98c'] },
    { id: 'f5', cat: 'Kitchen', name: 'Walnut Cutting Board', price: 68, palette: ['#8a6a4a', '#5e4730'] },
    { id: 'f6', cat: 'Bedroom', name: 'Stonewashed Sheet Set', price: 168, oldPrice: 220, badge: 'Sale', palette: ['#c9b59a', '#8a7558'] },
    { id: 'f7', cat: 'Living', name: 'Hand‑thrown Vase', price: 54, palette: ['#1f3a2e', '#3e5b4d'] },
    { id: 'f8', cat: 'Outdoor', name: 'Woven Picnic Basket', price: 89, badge: 'New', palette: ['#d8c9b6', '#a78f73'] },
  ];

  const deals = [
    { id: 'd1', name: 'Ceramic Mug Set (4)', price: 36, oldPrice: 52, discount: 30, palette: ['#efe2cd', '#c5b69b'] },
    { id: 'd2', name: 'Wool Area Rug 5×7', price: 320, oldPrice: 480, discount: 33, palette: ['#2c4337', '#4f6b5d'] },
    { id: 'd3', name: 'Cast Iron Skillet 10"', price: 58, oldPrice: 84, discount: 31, palette: ['#3a3a3a', '#1a1a1a'] },
    { id: 'd4', name: 'Glass Carafe & Cups', price: 44, oldPrice: 62, discount: 29, palette: ['#bcd5cb', '#7fa092'] },
  ];

  // --- SVG product illustration ------------------------------------------
  function productSvg(palette, seed) {
    const [a, b] = palette;
    const r = (seed * 37) % 100;
    return `
      <svg viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg" role="presentation" aria-hidden="true">
        <defs>
          <linearGradient id="g${seed}" x1="0" y1="0" x2="1" y2="1">
            <stop offset="0%" stop-color="${a}"/>
            <stop offset="100%" stop-color="${b}"/>
          </linearGradient>
        </defs>
        <rect width="200" height="200" fill="url(#g${seed})"/>
        <circle cx="${60 + (r % 30)}" cy="${70 + (r % 40)}" r="${42 + (r % 12)}" fill="rgba(255,255,255,.18)"/>
        <circle cx="${140 - (r % 25)}" cy="${135 + (r % 20)}" r="${28 + (r % 10)}" fill="rgba(0,0,0,.10)"/>
      </svg>`;
  }

  // --- Render featured products ------------------------------------------
  const featuredGrid = document.getElementById('featuredGrid');
  if (featuredGrid) {
    featuredGrid.innerHTML = featured.map((p, i) => {
      const sale = p.oldPrice;
      const badgeClass = p.badge === 'Sale' ? 'sale' : p.badge === 'New' ? 'new' : '';
      const badgeHtml = p.badge ? `<span class="product-badge ${badgeClass}">${p.badge}</span>` : '';
      const priceHtml = sale
        ? `<span class="price-new price-sale">$${p.price}</span><span class="price-old">$${p.oldPrice}</span>`
        : `<span class="price-new">$${p.price}</span>`;
      return `
        <li>
          <article class="product-card">
            <div class="product-thumb">
              ${badgeHtml}
              ${productSvg(p.palette, i + 1)}
            </div>
            <div class="product-body">
              <p class="product-cat">${p.cat}</p>
              <h3 class="product-name"><a href="#">${p.name}</a></h3>
              <p class="product-price">${priceHtml}</p>
              <button type="button" class="add-btn" data-id="${p.id}" data-name="${p.name}" aria-label="Add ${p.name} to cart">Add to cart</button>
            </div>
          </article>
        </li>`;
    }).join('');
  }

  // --- Render deals ------------------------------------------------------
  const dealsGrid = document.getElementById('dealsGrid');
  if (dealsGrid) {
    dealsGrid.innerHTML = deals.map((p, i) => `
      <li>
        <article class="deal-card">
          <div class="deal-thumb">${productSvg(p.palette, i + 20)}</div>
          <div class="deal-info">
            <span class="deal-discount">−${p.discount}%</span>
            <h3>${p.name}</h3>
            <p class="product-price">
              <span class="price-new price-sale">$${p.price}</span>
              <span class="price-old">$${p.oldPrice}</span>
            </p>
          </div>
          <button type="button" class="icon-btn add-btn-mini" data-id="${p.id}" data-name="${p.name}" aria-label="Add ${p.name} to cart">
            <svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true" focusable="false">
              <path d="M12 5v14M5 12h14" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>
            </svg>
          </button>
        </article>
      </li>`).join('');
  }

  // --- Cart --------------------------------------------------------------
  let cartItems = 0;
  const cartCount = document.getElementById('cartCount');
  const cartBtn = document.getElementById('cartBtn');
  const toast = document.getElementById('toast');
  let toastTimer;

  function showToast(msg) {
    if (!toast) return;
    toast.textContent = msg;
    toast.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => toast.classList.remove('show'), 2200);
  }

  function addToCart(name) {
    cartItems += 1;
    if (cartCount) {
      cartCount.textContent = String(cartItems);
      cartCount.style.display = cartItems > 0 ? 'grid' : 'none';
    }
    if (cartBtn) {
      cartBtn.setAttribute('aria-label', `Cart, ${cartItems} item${cartItems === 1 ? '' : 's'}`);
    }
    showToast(`Added “${name}” to cart`);
  }

  document.addEventListener('click', (e) => {
    const target = e.target instanceof Element ? e.target.closest('[data-id][data-name]') : null;
    if (target) {
      addToCart(target.getAttribute('data-name') || 'Item');
    }
  });

  // --- Deals countdown ---------------------------------------------------
  const timerEl = document.getElementById('dealTimer');
  if (timerEl) {
    const end = new Date();
    end.setHours(end.getHours() + 36);
    const pad = (n) => String(n).padStart(2, '0');
    const tick = () => {
      const ms = end - new Date();
      if (ms <= 0) { timerEl.textContent = '00:00:00'; return; }
      const h = Math.floor(ms / 3.6e6);
      const m = Math.floor((ms % 3.6e6) / 6e4);
      const s = Math.floor((ms % 6e4) / 1000);
      timerEl.textContent = `${pad(h)}:${pad(m)}:${pad(s)}`;
    };
    tick();
    setInterval(tick, 1000);
  }

  // --- Newsletter --------------------------------------------------------
  const form = document.getElementById('newsletterForm');
  const input = document.getElementById('emailInput');
  const status = document.getElementById('formStatus');
  if (form && input && status) {
    form.addEventListener('submit', (e) => {
      e.preventDefault();
      const value = input.value.trim();
      const valid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
      if (!valid) {
        status.textContent = 'Please enter a valid email address.';
        status.classList.add('error');
        input.setAttribute('aria-invalid', 'true');
        input.focus();
        return;
      }
      status.classList.remove('error');
      status.textContent = 'Thanks for subscribing — check your inbox to confirm.';
      input.removeAttribute('aria-invalid');
      input.value = '';
    });
  }

  // --- Year --------------------------------------------------------------
  const year = document.getElementById('year');
  if (year) year.textContent = new Date().getFullYear();
})();

